        Y = (float)(cos(angleXY * (double)6.2831855f) * (cosYZ * length));
        Z = (float)(sin(angleYZ * (double)6.2831855f) * length);
        return *this;
    }
    C3DVector& AccurateNormalise() {
        float m = (float)sqrt(X * X + Y * Y + Z * Z);
