    for (std::list<AgentVector*>::iterator list = AgentLists.begin(); list != AgentLists.end(); ++list) {
        for (AgentVector::iterator it = (*list)->begin(); it != (*list)->end(); ++it) {
            if (*it == agent) {
                AgentVector::iterator position = it;
                --it;
                (*list)->erase(position);
            }
        }
    }
}

